import type { ReactNode } from "react";
import type { QuizCategory, QuizExercise } from "./article01QuizData";
import { Unit4ConcordPassage, Unit4FillBlanks, Unit4ReadingOutline, Unit4TrueFalse, Unit4VerbChoices, Unit4VocabularyContext } from "./Unit4QuizInteractions";
import { Unit5BlankSentence, Unit5FlashbackPassage, Unit5PrefixQuestion, Unit5SentenceReveal, Unit5TimelineMatch } from "./Unit5QuizInteractions";
import { Unit7PresentStory, Unit7TextOutline, Unit9Attitudes, Unit9Loanwords, Unit9ModalChoices, Unit9ModalDialogues, UnitQuizMultiBlank } from "./Unit45QuizInteractions";

type Row = { prompt: ReactNode; answer: ReactNode; translation?: ReactNode; title?: string; instruction?: string };
const make = (title: string, prompt: ReactNode, answer: ReactNode, instruction?: string, answerTranslation?: ReactNode): QuizExercise => ({ title, prompt, answer, instruction, answerTranslation });
const inline = (title: string, prompt: ReactNode, instruction: string): QuizExercise => ({ title, prompt, instruction, answer: null, selfManagedAnswers: true });
const block = (content: ReactNode) => <blockquote className="quiz-question-card">{content}</blockquote>;
const rowSet = (prefix: string, rows: Row[], instruction: string): QuizExercise[] =>
  rows.map((row, index) => make(row.title || (prefix + " · " + String(index + 1).padStart(2, "0")), block(row.prompt), row.answer, row.instruction || instruction, row.translation));
const folderColors = ["#c6d4c8", "#e4c4bc", "#ccd5de", "#d6cee1", "#e6d2bd", "#e6c5b1", "#cdc0b7"] as const;
const folder = (id: string, label: string, colorIndex: number, exercises: QuizExercise[]): QuizCategory => ({
  id,
  label,
  color: folderColors[colorIndex],
  exercises,
});

type UnitData = {
  analytical: QuizExercise[];
  vocabulary: QuizExercise[];
  paraphrasing: QuizExercise[];
  prepositions: QuizExercise[];
  grammar: QuizExercise[];
  translation: QuizExercise[];
};

